// ============================================================================
// MODULE: vigil80_spi_receiver_16to8
// DESCRIPTION: Receives VIGIL80 SPI video stream.     
// Parameters SPI VIGIL80:
// CPOL = 1
// CPHA = 1
// MSB first
//
// VIGIL80 is SPI master:
// - video_sck  generated by camera
// - video_csb  active low, one chip select per frame
// - video_mosi data from camera to FPGA
//
// The first FRAME_PIX words are active image pixels.
// Footer words are discarded.
//
// Each input pixel is 16-bit thermal data.
// Output pixel is 8-bit grayscale.
//
// Conversion reference (input relative_temp, selectable at runtime):
//   0 = absolute : gray = (thermal - TEMP_MIN) >> TEMP_SHIFT
//                  (fixed reference: affected by the sensor drift)
//   1 = relative : gray = (thermal - base) >> TEMP_SHIFT
//                  base = frame mean - MEAN_OFFSET
//                  (the average scene sits MEAN_OFFSET raw units above
//                   gray 0: thresholds become "levels above the scene
//                   average", independent of drift)
//
// Why the mean and not the minimum: the minimum is decided by a single pixel,
// so anomalous cold pixels moved the whole image to white. In the mean each
// pixel counts 1/6400: a pixel stuck at 0 moves it by about 4 raw units.
//
// In relative mode the mean of the PREVIOUS frame is used: the mean of the
// current frame is known only after its last pixel, while its pixels must be
// converted as they arrive. One frame is 33 ms, the drift takes minutes, so
// the delay has no visible effect. After reset, until the first complete
// frame, TEMP_MIN is used.
//
// Defective pixels (plausibility check):
// a pixel stuck at a very low value (e.g. 0) would appear as a fixed dot.
// Any pixel below VALID_MIN is treated as defective: its value is replaced
// with the previous pixel of the stream (left neighbour in the same row)
// BEFORE the conversion and the mean. No pixel address is needed.
// Pixels stuck at a HIGH value are not detected (they show as a bright dot).
// ============================================================================

module vigil80_spi_receiver_16to8 #(
    parameter int FRAME_PIX    = 6400,
    parameter int FOOTER_WORDS = 23,
    parameter int TOTAL_WORDS  = FRAME_PIX + FOOTER_WORDS,
    parameter int ADDR_BITS    = $clog2(FRAME_PIX),

    parameter int TEMP_MIN     = 16'd28672,   //Minimum thermal value used as reference for the conversion
    parameter int unsigned TEMP_SHIFT   = 4,

    // Lowest plausible raw value: below it a pixel is considered defective
    // (16000 = about -113 C on the ICD scale, far below any real scene)
    parameter int VALID_MIN = 16'd16000,

    // Relative mode: distance of gray 0 below the frame mean (raw units).
    // 128 raw units = 32 gray levels with TEMP_SHIFT = 2 (about 1.3 K):
    // the average scene appears dark gray, colder areas black.
    parameter int MEAN_OFFSET = 128
)(
    input  logic rst_n,

    input  logic relative_temp,   // 0: absolute (TEMP_MIN), 1: relative (frame mean)

    input  logic video_sck,
    input  logic video_csb,
    input  logic video_mosi,

    input  logic wr_allow,

    output logic pix_valid,
    output logic [ADDR_BITS-1:0] pix_addr,
    output logic [7:0] pix_data,

    output logic frame_done
);

    localparam int WORD_CNT_BITS = $clog2(TOTAL_WORDS);

    // ========================================================================
    // SPI receiver
    // ========================================================================
    logic [15:0] shift_reg;    //shift register to build up the 16 bits word
    logic [3:0]  bit_cnt;      //to count from 0 to 15

    logic [WORD_CNT_BITS-1:0] word_cnt;  //Count how many 16-bit words have been received in the current frame

    logic frame_active;       // high while CS frame reception is active
    logic capture_enable;     //useful for preventing wr_allow change while saving 

    // =========================================================================
    // 16-bit thermal value to 8-bit grayscale conversion
    //
    // gray = clamp((thermal - base) >> TEMP_SHIFT)
    //
    // base = TEMP_MIN (absolute) or frame mean - MEAN_OFFSET (relative).
    // TEMP_SHIFT sets the contrast: 1 gray level = 2^TEMP_SHIFT raw units
    // (with TEMP_SHIFT = 2: 4 units = 0.04 K).
    // =========================================================================

function automatic logic [7:0] thermal16_to_gray8(
    input logic [15:0] thermal,
    input logic [15:0] base
);

    logic [15:0] diff;
    logic [15:0] scaled;

    begin

        if (thermal <= base) begin
            thermal16_to_gray8 = 8'd0;
        end
        else begin
            diff = thermal - base;
            scaled = diff >> TEMP_SHIFT;

            if (scaled >= 16'd255)
                thermal16_to_gray8 = 8'd255;
            else
                thermal16_to_gray8 = scaled[7:0];
        end
    end

endfunction


    // ========================================================================
    // SPI receiver
    // ========================================================================
    // IMPORTANT:
    // video_csb IS NOT in the sensitivity list.
    //
    // Once a frame has started, CSB is ignored until all 6423 words
    // have been received.
    // ========================================================================
    logic [15:0] completed_word;
    assign completed_word = {shift_reg[14:0], video_mosi};

    logic [15:0] vtemp_reg;

    // ========================================================================
    // Defective pixel correction
    // ========================================================================
    logic [15:0] prev_word;       // previous image pixel (left neighbour)
    logic        is_dead_pixel;   // 1 if the received value is not plausible
    logic [15:0] pixel_word;      // pixel value after the correction

    // A value below VALID_MIN cannot come from a real scene
    assign is_dead_pixel = (completed_word < 16'(VALID_MIN));

    // Defective pixel -> value of the previous pixel; otherwise unchanged
    assign pixel_word = is_dead_pixel ? prev_word : completed_word;

    // ========================================================================
    // Frame mean (relative reference)
    // ========================================================================
    // Sum of the FRAME_PIX pixels: at most 6400 * 65535 < 2^29
    localparam int SUM_BITS = $clog2(FRAME_PIX) + 16;          // 13 + 16 = 29

    // Division by FRAME_PIX done as a multiplication by its reciprocal:
    //   mean = sum / 6400  ~  (sum * MEAN_MULT) >> MEAN_SHIFT
    //   MEAN_MULT = round(2^25 / 6400) = 5243  (error about 0.003 %)
    // A multiplication by a constant avoids a slow divider.
    localparam int MEAN_SHIFT = 25;
    localparam int MEAN_MULT  = ((1 << MEAN_SHIFT) + FRAME_PIX / 2) / FRAME_PIX;

    logic [SUM_BITS-1:0]            frame_sum;   // running sum of the frame being received
    logic [SUM_BITS-1:0]            last_sum;    // sum including the pixel just completed
    logic [SUM_BITS+MEAN_SHIFT-1:0] sum_scaled;  // last_sum * MEAN_MULT
    logic [15:0]                    frame_mean;  // mean of the frame (valid at its last pixel)

    assign last_sum   = frame_sum + pixel_word;
    assign sum_scaled = last_sum * MEAN_MULT;
    assign frame_mean = 16'(sum_scaled >> MEAN_SHIFT);

    // ========================================================================
    // Conversion reference (absolute or relative)
    // ========================================================================
    logic [15:0] relative_base;   // frame mean - MEAN_OFFSET, of the last complete frame
    logic [15:0] conversion_base; // reference actually used by the conversion

   // relative_temp: HDMI domain -> video_sck domain
    logic relative_meta;   // first synchronizer FF (may become metastable)
    logic relative_sync;   // second synchronizer FF (stable)
    logic relative_frame;  // mode used by the current frame (latched at frame start)

    always_ff @(posedge video_sck or negedge rst_n) begin
        if (!rst_n) begin
            relative_meta <= 1'b0;
            relative_sync <= 1'b0;
        end
        else begin
            relative_meta <= relative_temp;
            relative_sync <= relative_meta;
        end
    end

    // Reference selected at runtime, constant during a whole frame
    assign conversion_base = relative_frame ? relative_base : 16'(TEMP_MIN);


    always_ff @(posedge video_sck or negedge rst_n) begin

        if (!rst_n) begin
            shift_reg <= 16'd0;
            bit_cnt <= 4'd0;
            word_cnt <= '0;

            frame_active <= 1'b0;
            capture_enable <= 1'b0;

            pix_valid <= 1'b0;
            pix_addr <= '0;
            pix_data <= 8'd0;
            frame_done <= 1'b0;

            frame_sum     <= '0;
            relative_base <= 16'(TEMP_MIN);     // until the first full frame
            prev_word     <= 16'(TEMP_MIN);
            relative_frame <= 1'b0;
        end
        else begin

            //default value
            pix_valid  <= 1'b0;
            frame_done <= 1'b0;

            // =================================================================
            // WAIT FOR FRAME START
            // =================================================================
            // CSB is used ONLY here.
            // If CSB is high, we simply wait.
            // =================================================================

            if (!frame_active) begin   //If we aren't recording any frames, we can start a new one
                if (!video_csb) begin  //chip selected active
                    // ---------------------------------------------------------
                    // New frame detected
                    // ---------------------------------------------------------
                    frame_active   <= 1'b1;
                    capture_enable <= wr_allow;  //At the beginning of frame,`wr_allow` is copied into `capture_enable`
                                                 //So the decision is made just once at the start of the frame
                                                 //to avoid that changes of wr_allow affects frame’s storage
                    word_cnt       <= '0;
                    frame_sum      <= '0;        // new frame: restart the sum
                    relative_frame <= relative_sync;  // conversion mode for this frame

                    // ---------------------------------------------------------
                    // First bit of first 16-bit word
                    // ---------------------------------------------------------
                    shift_reg <= {15'd0, video_mosi};  //first bit loaded into the shift register
                    bit_cnt   <= 4'd1;
                end
            end

            // =================================================================
            // FRAME ACTIVE
            // =================================================================
            // From this point onward CSB is deliberately ignored.
            // This protects the receiver against CSB glitches.
            // =================================================================
            else begin
                // -------------------------------------------------------------
                // Shift next bit
                // -------------------------------------------------------------
                shift_reg <= {shift_reg[14:0], video_mosi};

                // -------------------------------------------------------------
                // Complete 16-bit word
                // -------------------------------------------------------------

                if (bit_cnt == 4'd15) begin
                    bit_cnt <= 4'd0;

                    // =========================================================
                    // ACTIVE IMAGE
                    // =========================================================
                    if (capture_enable) begin
                        if (word_cnt < FRAME_PIX) begin
                            pix_valid <= 1'b1;
                            pix_addr <= word_cnt[ADDR_BITS-1:0];   //save the received pixel at the address corresponding to the number of the received word

                            // Must use concatenation because `shift_reg` would be updated at the end of the loop
                            pix_data <= thermal16_to_gray8(pixel_word, conversion_base);
                            //pix_data <= completed_word[7:0];
                            //pix_data <= (completed_word > 16'd25000) ? 8'd255 : 8'd0;
                        end
                        else if (word_cnt == FRAME_PIX) begin
                            // Prima parola footer = VTEMP
                            vtemp_reg <= completed_word;
                        end

                        // =========================================================
                        // LAST IMAGE PIXEL
                        // =========================================================
                        if (word_cnt == FRAME_PIX - 1) begin
                            frame_done <= 1'b1;  //After received all the TOTAL_WORDS, set frame_done = 1 only if that frame must be saved
                        end

                    end

                    // =========================================================
                    // FRAME MEAN (relative reference)
                    // =========================================================
                    // Computed on EVERY frame, also when the frame is not
                    // stored (capture_enable = 0): the pixels are received
                    // anyway, so the reference stays up to date.
                    // Footer words are not image pixels and are excluded.
                    // The corrected pixel is used (defective pixels replaced).
                    // =========================================================
                    if (word_cnt < FRAME_PIX) begin
                        frame_sum <= last_sum;
                        prev_word <= pixel_word;   // left neighbour for the next pixel
                    end

                    // Last image pixel: the mean of this frame is complete.
                    // base = mean - MEAN_OFFSET (0 if the mean is smaller)
                    // becomes the reference for the next frame.
                    if (word_cnt == FRAME_PIX - 1) begin
                        if (frame_mean > MEAN_OFFSET)
                            relative_base <= frame_mean - 16'(MEAN_OFFSET);
                        else
                            relative_base <= 16'd0;
                    end

                    // =========================================================
                    // END OF COMPLETE FRAME (6400 image words + 23 footer words)
                    // =========================================================

                    if (word_cnt == TOTAL_WORDS - 1) begin
                        word_cnt       <= '0;
                        frame_active   <= 1'b0;
                        capture_enable <= 1'b0;
                    end
                    else begin  //FRAME NOT COMPLETE
                        word_cnt <= word_cnt + 1'b1;
                    end

                end

                // -------------------------------------------------------------
                // Word not complete
                // -------------------------------------------------------------

                else begin
                    bit_cnt <= bit_cnt + 1'b1;
                end

            end
        end
    end

endmodule